#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 0x400
static char main_out[OUT_BUF_SIZE + 1];

static void to_camel(const char *src)
{
    size_t out_i = 0;
    int capitalize_next = 0;
    for (size_t i = 0; src[i] != '\0' && out_i < OUT_BUF_SIZE; ++i) {
        char c = src[i];
        if (c == '_') {
            capitalize_next = 1;
            continue;
        }
        if (capitalize_next) {
            c = (char)toupper((unsigned char)c);
            capitalize_next = 0;
        }
        main_out[out_i++] = c;
    }
    main_out[out_i] = '\0';
}

static void to_snake(const char *src)
{
    size_t out_i = 0;
    int first = 1;
    for (size_t i = 0; src[i] != '\0' && out_i < OUT_BUF_SIZE; ++i) {
        char c = src[i];
        if (isupper((unsigned char)c) && !first) {
            if (out_i < OUT_BUF_SIZE) {
                main_out[out_i++] = '_';
            }
            c = (char)tolower((unsigned char)c);
        } else {
            c = (char)tolower((unsigned char)c);
        }
        main_out[out_i++] = c;
        first = 0;
    }
    main_out[out_i] = '\0';
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
        puts(main_out);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
        puts(main_out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
